#include "ImageEngine.h"
#include <cassert>
#include <cstdint>
int main(){picsay::Image a; a.width=2;a.height=1;a.rgba={255,0,0,255,0,255,0,128};assert(picsay::invert(a));assert(a.rgba[0]==0&&a.rgba[1]==255);assert(picsay::grayscale(a));picsay::Image b;assert(picsay::rotate90(a,1,b));assert(b.width==1&&b.height==2);picsay::Image c;assert(picsay::crop(a,0,0,1,1,c));assert(c.valid());assert(picsay::pixelize(a,2));assert(picsay::boxBlur(a,1));assert(picsay::sharpen(a,1));assert(picsay::warpBulge(a,0,0,2,.2f));assert(picsay::blend(a,c,0,0,.5f));picsay::Image invalid;invalid.width=2147483647;invalid.height=2147483647;assert(!invalid.valid());assert(!picsay::crop(a,1,0,2147483647,1,b));uint32_t seed=0x12345678u;auto next=[&](){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;return seed;};for(int h=1;h<=12;h++)for(int w=1;w<=12;w++){picsay::Image test;test.width=w;test.height=h;test.rgba.resize(size_t(w)*h*4);for(auto&v:test.rgba)v=uint8_t(next());picsay::Image rotated;assert(picsay::rotate90(test,1,rotated));assert(rotated.valid()&&rotated.width==h&&rotated.height==w);picsay::Image roundTrip;assert(picsay::rotate90(rotated,3,roundTrip));assert(roundTrip.valid()&&roundTrip.width==w&&roundTrip.height==h);assert(roundTrip.rgba==test.rgba);picsay::Image blended=test;assert(picsay::blend(blended,test,0,0,1.f));assert(blended.valid());assert(picsay::boxBlur(blended,1));assert(blended.valid());assert(picsay::sharpen(blended,.5f));assert(blended.valid());}picsay::Image empty;assert(!picsay::invert(empty));assert(!picsay::boxBlur(empty,1));assert(!picsay::pixelize(empty,2));return 0;}